// Run first. Returns the 10 nearest docs with id, title and distance, in rank order.
// The caller collects the ids for the next query.
query nearest_docs($q: Vector(3)) {
    match { $d: Doc }
    return { $d.id, $d.title, nearest($d.embedding, $q) as distance }
    order { nearest($d.embedding, $q) }
    limit 10
}

// Run second, with $ids set to the ids from the first query's rows.
// The caller joins the results on id and fills in the cites count.
// A doc missing from this result cites nothing, so the caller sets its cites to 0.
// A single query can't do this: the cites traversal drops docs that have no cites.
query cite_counts($ids: [String]) {
    match {
        $d: Doc
        $d.id in $ids
        $d cites $c
    }
    return { $d.id, count($c) as cites }
}

