// Run first: people who know at least one person, with their degree, most connected first.
query connected_people() {
    match {
        $p: Person
        $p knows $f
    }
    return {
        $p.handle,
        $p.name,
        count($f) as degree
    }
    order { degree desc }
}

// Run second: people who know nobody. The caller appends these to the first result with degree = 0 (they sort last).
query isolated_people() {
    match {
        $p: Person
        not { $p knows $_ }
    }
    return { $p.handle, $p.name }
}

