answer.text:
// GQ has no unbounded traversal (`knows{1,}` is rejected, T15), so "any number of hops"
// cannot be a single query. The caller runs this one-hop query in a loop:
// 1. Run it with $from = the starting handle.
// 2. Add every returned name to a result set (dedupe names in the caller).
// 3. Re-run it with each newly seen handle as $from, skipping handles already expanded.
// 4. Stop when a round returns no unseen handles. The result set is then everyone
//    reachable via knows, so the caller treats it as the final distinct names.
query knows_one_hop($from: String) {
    match {
        $p: Person { handle: $from }
        $p knows $f
    }
    return distinct { $f.handle, $f.name }
}

