// GQ has no arithmetic over scores, so the 0.7/0.3 weighted sum cannot be expressed.
// This uses reciprocal rank fusion (rrf) of the vector and BM25 rankings as the closest available fusion.
query hybrid_docs($q: String, $v: Vector(3)) {
    match {
        $d: Doc
        match_text($d.body, $q)
    }
    return {
        $d.title,
        rrf(nearest($d.embedding, $v), bm25($d.body, $q)) as s
    }
    order { rrf(nearest($d.embedding, $v), bm25($d.body, $q)) }
    limit 10
}

