// GQ has no unbounded traversal ({1,} is rejected), so "any number of hops" can't be a single query.
// This returns everyone within 10 knows-hops of $from. Hops are shortest-path distances, so the
// caller checks completeness: if any reached person is at the edge of the bound, re-run with a
// larger literal bound (e.g. {1,20}) and compare the name sets. When two successive bounds
// return the same set of names, that set is the full transitive closure.
query reachable_names($from: String) {
    match {
        $p: Person { handle: $from }
        $p knows{1,10} $f
    }
    return distinct { $f.name }
}

