// Run first. People who know at least one person, with their degree, most connected first.
// Grouping is on the non-aggregated fields, so handle (the key) is included to keep
// distinct people who share a name from being merged.
query people_with_friends() {
    match {
        $p: Person
        $p knows $f
    }
    return {
        $p.handle,
        $p.name,
        count($f) as degree
    }
    order { degree desc }
}

// Run second. People who know nobody. GQ has no optional match, so the first query
// cannot return them. The caller gives each of these degree 0 and appends them after
// the first query's rows, which keeps the order by degree descending.
query people_with_no_friends() {
    match {
        $p: Person
        not { $p knows $_ }
    }
    return { $p.handle, $p.name }
}

