// GQ cannot express unbounded reachability: bounds must be finite, and `{1,}` is rejected.
// The caller runs this first query to get the people directly known by $from.
// It keeps the returned handles as the "visited" set and as the first frontier.
query known_by_handle($from: String) {
    match {
        $p: Person { handle: $from }
        $p knows $f
    }
    return distinct { $f.handle, $f.name }
}

// The caller repeats this query, passing the handles that are new since the last round as $frontier.
// It adds each returned person not already in the visited set, and those new handles become the next frontier.
// It stops when a round returns no new handles.
// The distinct names of everyone in the visited set, minus $from itself unless it was reached through a cycle, are the answer.
query known_by_frontier($frontier: [String]) {
    match {
        $p: Person
        $p.handle in $frontier
        $p knows $f
    }
    return distinct { $f.handle, $f.name }
}

