// GQ cannot do this in one query: a mutation has no match/order/limit,
// and `nearest` works only in a read query's `order`. This is step 1 and
// returns the ids of the 20 nearest docs. Step 2 is a separate mutation:
//   query tag_near($ids: [String]) {
//       update Doc set { tags: ["near"] } where id in $ids
//   }
query nearest_docs($q: Vector(3)) {
    match { $d: Doc }
    return { $d.id }
    order { nearest($d.embedding, $q) }
    limit 20
}

