query touchpoints_per_watched_source($channel: String) {
    match {
        $c: Channel { slug: $channel }
        $c channelWatchesSource $s
        $t touchpointOnSource $s
    }
    return {
        $s.slug
        count($t) as touchpoints
    }
    order { touchpoints desc }
}

