answer.text:
// Run first. The caller keeps the returned ids (the 10 nearest documents among all documents) and passes them as $ids to the second query.
query nearest_docs($q: Vector(3)) {
    match { $d: Doc }
    return { $d.id }
    order { nearest($d.embedding, $q) }
    limit 10
}

// Run second, with $ids = the ids from the first query. The result is the titles of those documents that belong to the collection $coll.
query titles_in_collection($ids: [String], $coll: String) {
    match {
        $d: Doc
        $d.id in $ids
        $c: Collection { slug: $coll }
        $d "in" $c
    }
    return { $d.title }
}

