// GQ (edition 2) has no arithmetic expressions, so `twice`, `born_about`
// and the `age * 2 >= $min` filter cannot be written. This query returns the
// raw inputs (name, age) for people with a known age; the doubling, the
// 2026 - age value and the $min comparison must be applied by the caller.
query people_by_doubled_age($min: I32) {
    match {
        $p: Person
        $p.age is not null
    }
    return { $p.name, $p.age }
}

